def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    myD = 0
    for a in my:
        if a == 'D':
            myD += 1

    oppD = 0
    for a in op:
        if a == 'D':
            oppD += 1

    last_my = my[-1]
    last_op = op[-1]

    if oppD == 0:
        if myD == 0:
            if n >= 8:
                return 'D'
            return 'C'
        if myD == 1 and last_my == 'D' and last_op == 'C':
            return 'C'
        return 'D'

    def_streak = 0
    for a in reversed(op):
        if a == 'D':
            def_streak += 1
        else:
            break

    recent5 = op[-5:]
    recent10 = op[-10:]

    recent5_def = 0
    for a in recent5:
        if a == 'D':
            recent5_def += 1

    recent10_def = 0
    for a in recent10:
        if a == 'D':
            recent10_def += 1

    opp_coop = (n - oppD) / n

    my_score = 0
    opp_score = 0
    for i in range(n):
        a = my[i]
        b = op[i]
        if a == 'C':
            if b == 'C':
                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1

    forgive = 0
    punish = 0
    for i in range(n - 1):
        if my[i] == 'D' and op[i] == 'C':
            if op[i + 1] == 'C':
                forgive += 1
            else:
                punish += 1

    if last_op == 'D':
        if def_streak == 1:
            if last_my == 'C':
                if n >= 2 and my[n - 2] == 'D' and op[n - 2] == 'C' and opp_coop > 0.55:
                    return 'C'
                return 'D'
            if opp_coop > 0.75 and recent5_def <= 2:
                return 'C'
            return 'D'

        if def_streak == 2:
            if last_my == 'C':
                if opp_coop > 0.7 and recent5_def <= 3 and forgive > punish:
                    return 'C'
                return 'D'
            if opp_coop > 0.75 and recent5_def <= 3:
                return 'C'
            return 'D'

        if opp_coop > 0.85 and recent5_def <= 3 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if opp_coop < 0.4 or recent10_def >= 6:
        return 'D'

    if last_my == 'D' and opp_coop < 0.6:
        return 'D'

    if opp_coop > 0.8 and recent10_def <= 2:
        if forgive >= 2 and punish == 0:
            if rng.random() < 0.12:
                return 'D'
        elif myD > 0 and rng.random() < 0.025:
            return 'D'

    if my_score < opp_score - 25 and opp_coop > 0.5 and recent5_def <= 2:
        if rng.random() < 0.07:
            return 'D'

    return 'C'
